static PyObject *
_color_lut_generate_power(PyObject *self, PyObject *args) {
    int size1D, size2D, size3D;
    double r_exp, g_exp, b_exp;
    int channels;

    if (!PyArg_ParseTuple(args, "idddi", &size1D, &size2D, &size3D, &r_exp, &g_exp, &b_exp, &channels)) {
        return NULL;
    }

    if (channels != 3) {
        PyErr_SetString(PyExc_ValueError, "Only 3 channels supported for now");
        return NULL;
    }

    Py_ssize_t table_size = (Py_ssize_t)size1D * size2D * size3D * channels;
    PyObject *table = PyList_New(table_size);
    if (!table) return NULL;

    int idx = 0;
    double inv_1d = (size1D > 1) ? 1.0 / (size1D - 1) : 0;
    double inv_2d = (size2D > 1) ? 1.0 / (size2D - 1) : 0;
    double inv_3d = (size3D > 1) ? 1.0 / (size3D - 1) : 0;

    for (int b = 0; b < size3D; b++) {
        double fb = b * inv_3d;
        for (int g = 0; g < size2D; g++) {
            double fg = g * inv_2d;
            for (int r = 0; r < size1D; r++) {
                double fr = r * inv_1d;

                // Apply power transform: output = 255 * (input/255)^exp
                // But input is 0-1, so: output = 255 * input^exp
                double new_r = floor(255.0 * pow(fr, r_exp));
                double new_g = floor(255.0 * pow(fg, g_exp));
                double new_b = floor(255.0 * pow(fb, b_exp));

                // Clip to [0, 255]
                if (new_r < 0) new_r = 0;
                if (new_r > 255) new_r = 255;
                if (new_g < 0) new_g = 0;
                if (new_g > 255) new_g = 255;
                if (new_b < 0) new_b = 0;
                if (new_b > 255) new_b = 255;

                PyList_SET_ITEM(table, idx++, PyFloat_FromDouble(new_r));
                PyList_SET_ITEM(table, idx++, PyFloat_FromDouble(new_g));
                PyList_SET_ITEM(table, idx++, PyFloat_FromDouble(new_b));
            }
        }
    }

    return table;
}

